create table if not exists akash_providers(id varchar(160) primary key,base_url text not null,region varchar(80) not null,models text[] not null,priority integer not null default 100,input_microusd_per_million bigint not null,output_microusd_per_million bigint not null,fixed_microusd bigint not null default 0,enabled boolean not null default true,health_status varchar(20) not null default 'unknown',last_health_at timestamptz,metadata jsonb not null default '{}',updated_at timestamptz not null default now());
create table if not exists akash_deployments(id uuid primary key,agent_id uuid,quote_id uuid not null references service_quotes(id),external_id varchar(180),provider_id varchar(160),image text not null,cpu_millis integer not null,memory_mib integer not null,gpu_model varchar(80),gpu_units integer not null default 0,max_hours integer not null,status varchar(24) not null check(status in('creating','active','closing','closed','failed')),close_after timestamptz not null,error varchar(500),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists akash_deployments_close_idx on akash_deployments(status,close_after);
insert into schema_migrations(version) values('006_akash') on conflict do nothing;
